// Normaliza os números (aceita "1.234,5" e "12") e separa os itens críticos
const num = (v) => {
  if (typeof v === 'number') return v;
  const n = Number(String(v ?? '').replace(/\./g, '').replace(',', '.').trim());
  return Number.isFinite(n) ? n : null;
};

const criticos = [];
const invalidos = [];

for (const item of $input.all()) {
  const r = item.json;
  const qtd = num(r['Quantidade']);
  const min = num(r['Estoque Minimo']);
  if (!r['Produto']) continue;                       // linha vazia
  if (qtd === null || min === null) { invalidos.push(r['Produto']); continue; }
  if (qtd <= min) {
    criticos.push({
      produto: r['Produto'],
      sku: r['SKU'] || '-',
      quantidade: qtd,
      minimo: min,
      faltam: Math.max(min - qtd, 0),
      zerado: qtd <= 0,
    });
  }
}

// Zerados primeiro, depois os que estão mais abaixo do mínimo
criticos.sort((a, b) => (b.zerado - a.zerado) || (b.faltam - a.faltam));

const linhas = criticos.map(c =>
  `<tr${c.zerado ? ' style="background:#fde2e2"' : ''}>` +
  `<td>${c.produto}</td><td>${c.sku}</td><td align="right">${c.quantidade}</td>` +
  `<td align="right">${c.minimo}</td><td align="right"><b>${c.faltam}</b></td></tr>`
).join('');

const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const zerados = criticos.filter(c => c.zerado).length;

let html = `<p>Relatório de estoque de <b>${hoje}</b>: <b>${criticos.length}</b> item(ns) no mínimo ou abaixo dele` +
  (zerados ? `, sendo <b>${zerados}</b> zerado(s)` : '') + `.</p>` +
  `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px">` +
  `<tr style="background:#eeeeee"><th>Produto</th><th>SKU</th><th>Qtd. atual</th><th>Mínimo</th><th>Faltam</th></tr>` +
  linhas + `</table>`;

if (invalidos.length) {
  html += `<p style="color:#a15c00">Atenção: não foi possível ler a quantidade ou o mínimo de: ${invalidos.join(', ')}.</p>`;
}

return [{ json: {
  total: criticos.length,
  zerados,
  assunto: `Estoque crítico: ${criticos.length} item(ns) precisam de reposição (${hoje})`,
  html,
}}];
